function paintSource(ctx,source,r){ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='medium';ctx.fillStyle='#100f18';ctx.fillRect(r.x,r.y,r.w,r.h);if(source.paint){source.paint(ctx,r);return;}if(source.tiles){const {images,rows,cols}=source.tiles,tw=source.width/cols,th=source.height/rows,sx=r.w/source.width,sy=r.h/source.height;images.forEach((im,i)=>{const x=(i%cols)*tw,y=Math.floor(i/cols)*th,k=Math.min(tw/im.width,th/im.height);ctx.drawImage(im,r.x+(x+(tw-im.width*k)/2)*sx,r.y+(y+(th-im.height*k)/2)*sy,im.width*k*sx,im.height*k*sy);});return;}if(source.pictures){for(const p of source.pictures)ctx.drawImage(p.image,r.x+p.x/source.width*r.w,r.y+p.y/source.height*r.h,p.w/source.width*r.w,p.h/source.height*r.h);return;}ctx.drawImage(source,r.x,r.y,r.w,r.h);}
const totalEditor=AccEditor.create((ctx,l)=>{ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='medium';const r=l.rect;if(l.uidText){paintUidText(ctx,l);return;}if(l.overlay){fit(ctx,l.source,r.x,r.y,r.w,r.h,true,false);if(l.priority)miscDecorations(ctx,r,l.entry);return;}if(l.id==='accessories'){ctx.fillStyle='#100f18';ctx.fillRect(r.x,r.y,r.w,r.h);}else paintSource(ctx,l.source,r);if(l.boxes)for(const b of l.boxes){const x=r.x+b.x/l.source.width*r.w,y=r.y+b.y/l.source.height*r.h,w=b.w/l.source.width*r.w,h=b.h/l.source.height*r.h;if(b.misc)fit(ctx,b.image,x,y,w,h,true,false);else{if(b.image)ctx.drawImage(b.image,x,y,w,h);yellowBorder(ctx,x,y,w,h,b.key?'car':'uid');}if(b.key)drawTickets(ctx,b.key,x,y,w,h);if(b.misc)miscDecorations(ctx,{x,y,w,h},b.misc);}},canvas=>{if(el('autoColor').checked)LVColor.apply(canvas);});
async function readUidImage(image,cropped=false){const preview=cut(image,[0,0,image.width,image.height],2400),api=window.pywebview?.api;if(api?.read_uid)return api.read_uid(preview.toDataURL('image/png').split(',')[1],cropped);if(!window.LV_PYTHON?.token)throw Error('Chưa nối được bộ đọc UID. Mở EXE đã build từ bản 16, không mở index.html trực tiếp.');const blob=await new Promise(resolve=>preview.toBlob(resolve,'image/png'));let response;try{response=await fetch('/api/uid',{method:'POST',headers:{'Content-Type':'image/png','X-LV-Token':window.LV_PYTHON.token,'X-LV-UID-Crop':cropped?'1':'0'},body:blob});}catch{throw Error('Không kết nối được bộ đọc UID. Cần mở EXE mới đã build từ bản 16.');}if(!response.ok){const body=await response.json().catch(()=>({}));throw Error(response.status===404?'EXE hiện tại chưa có đọc UID. Cần build lại bản 16.':body.error||'Không đọc được UID');}return response.json();}
async function scanUid(force=false){if(uidManual&&!force)return;if(!groups.background.length)return;el('uidReadStatus').textContent='Đang tìm UID trong ảnh nền…';let lastError=null;for(const e of groups.background){try{if(force||!e.uidResult)e.uidResult=await readUidImage(e.img);if(/^\d{8,14}$/.test(e.uidResult.uid||'')&&e.uidResult.confidence>=35){el('uidText').value=e.uidResult.uid;uidManual=false;el('uidReadStatus').textContent='UID từ '+e.file.name+' · hãy kiểm tra số trước khi xuất.';return;}}catch(error){lastError=error;}}
el('uidReadStatus').textContent=lastError?lastError.message:'Chưa tìm được UID rõ. Có thể nhập số bằng tay.';}
function paintUidText(ctx,l){const r=l.rect,label='ID '+el('uidText').value.trim(),size=r.h*.70;ctx.save();ctx.translate(r.x,r.y);ctx.font='900 '+size+'px '+ticketFont;ctx.textBaseline='middle';ctx.lineJoin='round';ctx.strokeStyle='#ff0000';ctx.fillStyle='#ffffff';ctx.lineWidth=Math.max(2,r.h*.07);const measured=ctx.measureText(label).width,available=Math.max(1,r.w-ctx.lineWidth*2);ctx.scale(Math.min(1,available/Math.max(1,measured)),1);ctx.strokeText(label,ctx.lineWidth,r.h/2);ctx.fillText(label,ctx.lineWidth,r.h/2);ctx.restore();}
