 const width=widths.reduce((a,b)=>a+b,0)+(acc?acc.canvas.width:0)||1200,featured=blocks['noi-bat'],fh=featured?Math.round(featured.height*width/featured.width*heightPercent('featuredHeight')):0,bgs=groups.background,bw=width/Math.max(1,bgs.length),bh=bgs.length?Math.round(Math.max(...bgs.map(e=>bw*e.img.height/e.img.width*heightPercent('bgHeight')))):0,bodyH=(body.length||acc||priority.length)?height:0,totalH=bh+fh+bodyH,sceneWidth=width,scale=Math.min(el('bestQuality').checked?Infinity:1,5000/sceneWidth,5000/totalH),cw=Math.max(1,Math.floor(sceneWidth*scale)),mainCW=Math.max(1,Math.round(width*scale)),ch=Math.max(1,Math.floor(totalH*scale)),layers=[];
 if(bh){const header=mk(mainCW,Math.max(1,Math.round(bh*scale))),ctx=header.getContext('2d'),boxes=[];ctx.fillStyle='#100f18';ctx.fillRect(0,0,header.width,header.height);header.pictures=[];bgs.forEach((e,i)=>{const left=Math.round(i*bw*scale),right=Math.round((i+1)*bw*scale),tileW=right-left,tileH=header.height,r=Math.min(tileW/e.img.width,tileH/(e.img.height*heightPercent('bgHeight'))),dw=e.img.width*r,dh=e.img.height*r*heightPercent('bgHeight'),dx=left+(tileW-dw)/2,dy=(tileH-dh)/2;ctx.drawImage(e.img,dx,dy,dw,dh);header.pictures.push({image:e.img,x:dx,y:dy,w:dw,h:dh});if(i===Number(el('profileIndex').value)-1&&groups.uid.length){drawUid(ctx,e.img,dx,dy,dw,dh);const w=Math.max(5,Math.round(dw*.443)),h=Math.max(5,Math.round(w*groups.uid[0].img.height/groups.uid[0].img.width)),x=Math.round(dx+dw*.347),y=Math.round(dy+dh*.80);boxes.push({x,y,w,h:Math.min(h,Math.max(5,Math.round(dy+dh-y))),image:groups.uid[0].img});}});layers.push({id:'background',source:header,boxes,rect:{x:0,y:0,w:mainCW,h:header.height}});}
