 for(const k of order){const source=k==='accessories'?acc.canvas:blocks[k],w=k==='accessories'?acc.canvas.width:widths[body.indexOf(k)],left=Math.round(x*scale),right=Math.min(cw,Math.round((x+w)*scale)),top=Math.round((bh+fh)*scale),bottom=Math.min(ch,Math.round((bh+fh+height)*scale));layers.push({id:k,source,boxes:k==='accessories'?acc.boxes.filter(b=>!b.misc||!b.misc.miscPriority):undefined,rect:{x:left,y:top,w:Math.max(1,right-left),h:Math.max(1,bottom-top)}});x+=w;}
 priority.forEach(e=>{const k=Math.min(gunCell.w/e.img.width,totalH*.35/e.img.height,width*.35/e.img.width),w=Math.max(1,Math.round(e.img.width*k*scale)),h=Math.max(1,Math.round(e.img.height*k*scale));layers.push({id:'misc-'+e.url,label:'Ưu tiên · '+e.file.name,source:e.img,overlay:true,priority:true,entry:e,rect:{x:(cw-w)/2,y:(ch-h)/2,w,h}});});
 if(/^\d{8,14}$/.test(el('uidText').value.trim())){const w=Math.min(cw*.40,1000),h=Math.max(30,w*.12);layers.push({id:'uid-text',label:'Chữ ID',uidText:true,overlay:true,rect:{x:(cw-w)/2,y:Math.max(0,Math.round(bh*scale)-h),w,h}});}
