let updating=false,loadingFiles=false,queuedUpdate=false,gunSignature='',suppressGunChange=false;
async function waitGunTool(){const frame=el('gunFrame');for(let i=0;i<150;i++){if(frame.contentWindow?.LVGuns)return frame.contentWindow.LVGuns;await new Promise(r=>setTimeout(r,100));}throw Error('Tool súng chưa tải. Hãy đóng rồi mở lại app.');}
function takeGunSnapshot(snapshot){gunReviewCount=snapshot.unresolved||0;const c=snapshot.canvas;if(c.hidden||!snapshot.count){gunBlock=null;return;}const ratio=Math.min(1,5000/c.width,5000/c.height),copy=mk(Math.max(1,Math.floor(c.width*ratio)),Math.max(1,Math.floor(c.height*ratio)));copy.getContext('2d').drawImage(c,0,0,copy.width,copy.height);copy.paint=snapshot.paint;gunBlock=copy;gunCell={w:snapshot.cellW*ratio,h:snapshot.cellH*ratio};}
async function updateAll(forceGuns=false){if(updating||loadingFiles){queuedUpdate=true;return;}queuedUpdate=false;updating=true;el('folder').disabled=true;el('clear').disabled=true;el('runGuns').disabled=true;try{const signature=groups.guns.map(e=>e.url).join('|');if(groups.guns.length&&(forceGuns||signature!==gunSignature)){el('outputStatus').textContent='Đang tự cắt súng và đọc LV…';const tool=await waitGunTool();suppressGunChange=true;const result=await tool.importFiles(groups.guns.map(e=>e.file));takeGunSnapshot(result);gunSignature=signature;if(result.unresolved)el('gunHint').textContent=result.unresolved+' ảnh súng chưa rõ LV/vùng cắt. Mở phần này để sửa; ảnh tổng sẽ cập nhật theo.';else el('gunHint').textContent='Đã đọc '+result.count+' ảnh súng. Sửa LV/vùng cắt ở đây nếu cần.';}await scanUid();await compose();}catch(e){el('outputStatus').textContent='Chưa cập nhật: '+e.message;}finally{suppressGunChange=false;updating=false;el('folder').disabled=false;el('clear').disabled=false;el('runGuns').disabled=false;if(queuedUpdate){queuedUpdate=false;scheduleCompose();}}}
window.LVAccGunProgress=(done,total)=>{if(updating)el('outputStatus').textContent='Đang cắt súng và đọc LV: '+done+'/'+total+' ảnh…';};
window.LVAccGunChanged=snapshot=>{if(suppressGunChange||updating||loadingFiles)return;takeGunSnapshot(snapshot);gunSignature=groups.guns.map(e=>e.url).join('|');scheduleCompose();};
function clearAccount(){uidManual=false;el('uidText').value='';el('uidReadStatus').textContent='';keepPriorityScene=false;selectPriority=null;suppressGunChange=true;el('gunFrame').contentWindow?.LVGuns?.clear();suppressGunChange=false;for(const arr of Object.values(groups))for(const e of arr)URL.revokeObjectURL(e.url);groups=Object.fromEntries(Object.keys(labels).map(k=>[k,[]]));gunBlock=null;gunSignature='';gunReviewCount=0;gunCell={w:400,h:196};excludedCars.clear();chosenMisc.clear();carTickets.clear();carOrder=[];clearTimeout(composeTimer);totalEditor.clear();window.LVApplySavedLayout?.();blocks={};el('outputs').replaceChildren();el('blockOutputs').replaceChildren();renderGroup();el('status').textContent='Đã xóa bộ ảnh';el('sizeHint').textContent='Giới hạn 5000 × 5000 px';}
async function loadAndUpdate(files,forced,reset=false){if(updating||loadingFiles){el('outputStatus').textContent='Chờ bộ ảnh hiện tại xử lý xong rồi thêm ảnh.';return;}if(reset)clearAccount();loadingFiles=true;el('folder').disabled=true;el('clear').disabled=true;try{await loadFiles(files,forced);}finally{loadingFiles=false;el('folder').disabled=false;el('clear').disabled=false;}await updateAll();}
// Native folder dialog bypasses the browser directory-upload confirmation.
el('folder').onclick=event=>{const api=window.pywebview?.api;if(!api?.choose_acc_folder)return;event.preventDefault();event.stopPropagation();importNativeFolder(api).catch(error=>{el('outputStatus').textContent='Chưa mở được thư mục: '+error.message;});};
async function importNativeFolder(api){if(updating||loadingFiles||el('folder').disabled)return;el('folder').disabled=true;try{const result=await api.choose_acc_folder();if(result.cancelled)return;const known=result.files.filter(item=>groupOf({webkitRelativePath:item.relativePath}));if(!known.length)throw Error('Không thấy ảnh trong các thư mục acc đã biết.');const files=new Array(known.length);let cursor=0,done=0;const direct=result.binary&&window.LV_PYTHON?.token;async function worker(){while(cursor<known.length){const i=cursor++,meta=known[i];let bytes,mime;if(direct){const response=await fetch('/api/import-image/'+encodeURIComponent(meta.id),{headers:{'X-LV-Token':window.LV_PYTHON.token}});if(!response.ok)throw Error('Không mở được ảnh '+meta.name+' (HTTP '+response.status+')');bytes=await response.arrayBuffer();mime=response.headers.get('Content-Type');}else{const item=await api.read_acc_image(meta.id);bytes=Uint8Array.from(atob(item.base64),c=>c.charCodeAt(0));mime=item.mime;}const file=new File([bytes],meta.name,{type:mime,lastModified:meta.lastModified});Object.defineProperty(file,'webkitRelativePath',{value:meta.relativePath});files[i]=file;done++;el('status').textContent='Đang nạp ảnh '+done+'/'+known.length+'…';}}const jobs=await Promise.allSettled(Array.from({length:direct?Math.min(4,known.length):1},()=>worker()));const failed=jobs.find(job=>job.status==='rejected');if(failed)throw failed.reason;await loadAndUpdate(files,undefined,true);}finally{el('folder').disabled=false;}}
el('folder').onchange=async e=>{const files=[...e.target.files];e.target.value='';try{await loadAndUpdate(files,undefined,true);}catch(err){el('outputStatus').textContent=err.message;}};
el('files').onchange=async e=>{const files=[...e.target.files];e.target.value='';await loadAndUpdate(files,el('group').value);};el('group').onchange=renderGroup;
el('apply').onclick=()=>{const r=['left','top','right','bottom'].map(id=>Number(el(id).value));if(!r.every(Number.isFinite)||r[2]<=r[0]||r[3]<=r[1]){el('groupHint').textContent='Tọa độ không hợp lệ';return;}if(el('group').value==='cars'){vehicleRegion=r;for(const e of groups.cars)e.cards=null;excludedCars.clear();carOrder=[];}else rects[el('group').value]=r;invalidate();renderGroup();scheduleCompose();};el('compose').onclick=()=>updateAll();
for(const id of ['scale','baseW','baseH','featured','featuredN','tileW','customChar','charRows','charCols','customItems','itemRows','itemCols','carRows','profileIndex','showBlocks','bgHeight','featuredHeight','showTickets','bestQuality','charFormMode','carBorderColor','carBorderPx','autoColor'])el(id).onchange=()=>{if(id==='charFormMode'){el('charForm').value='auto';totalEditor.forget('nhan-vat');totalEditor.forget('noi-bat');}invalidate();renderGroup();scheduleCompose();};
el('clear').onclick=()=>{if(updating||loadingFiles)return;clearAccount();};
el('runGuns').onclick=()=>updateAll(true);
el('takeGuns').onclick=async()=>{try{const tool=await waitGunTool(),snapshot=tool.snapshot();if(updating||snapshot.busy)throw Error('Chờ tool súng xử lý xong');takeGunSnapshot(snapshot);await compose();}catch(e){el('outputStatus').textContent=e.message;}};
el('uidText').oninput=()=>{uidManual=true;const value=el('uidText').value.trim();el('uidReadStatus').textContent=value&&!/^\d{8,14}$/.test(value)?'Nhập 8–14 chữ số UID, không gồm chữ ID.':'';scheduleCompose();};
el('readUid').onclick=async()=>{if(updating||loadingFiles)return;el('readUid').disabled=true;try{await scanUid(true);await compose();}finally{el('readUid').disabled=false;}};
el('moveUid').onclick=()=>totalEditor.select('uid-text');
el('uidFontSize').onchange=()=>{const value=Number(el('uidFontSize').value),layer=totalEditor.getLayers().find(l=>l.id==='uid-text');if(!layer||!Number.isFinite(value)||value<8||value>800)return;const factor=value/(layer.rect.h*.70);totalEditor.resize('uid-text',layer.rect.w*factor,layer.rect.h*factor);};
renderGroup();

el('miscFiles').onchange=async e=>{const files=[...e.target.files];e.target.value='';await loadAndUpdate(files,'misc');};

el('carFiles').onchange=async e=>{const files=[...e.target.files];e.target.value='';await loadAndUpdate(files,'cars');};el('uidFiles').onchange=async e=>{if(updating||loadingFiles)return;for(const entry of groups.uid)URL.revokeObjectURL(entry.url);groups.uid=[];const files=[...e.target.files];e.target.value='';await loadAndUpdate(files,'uid');};

el('blocksPanel').ontoggle=()=>{el('showBlocks').checked=el('blocksPanel').open;if(Object.keys(blocks).length)try{showOutputs();}catch(e){el('outputStatus').textContent=e.message;}};

function movingMisc(){return groups.misc.find(e=>e.url===el('miscMoveItem').value&&chosenMisc.has(e));}
function syncMiscPositionFields(){const e=movingMisc(),b=miscPreviewLayout.find(b=>b.misc===e),c=el('miscPreview');if(!b)return;for(const [id,value]of [['miscX',b.x/c.width*100],['miscY',b.y/c.height*100],['miscW',b.w/c.width*100],['miscH',b.h/c.height*100]])el(id).value=Math.round(value*10)/10;}
function containedMisc(position){const w=Math.max(.01,Math.min(1,position.w)),h=Math.max(.01,Math.min(1,position.h));return {x:Math.max(0,Math.min(1-w,position.x)),y:Math.max(0,Math.min(1-h,position.y)),w,h};}
function setMiscPosition(e,x,y,w,h){e.miscPosition=containedMisc({x,y,w,h});totalEditor.forget('misc-'+e.url);}
el('editMiscTotal').onclick=()=>{const e=movingMisc();if(!e)return;if(!e.miscPriority){el('miscHint').textContent='Bật Ưu tiên cho ảnh này trước khi kéo tự do trong ảnh tổng. Ảnh thường đổi thứ tự bằng kéo thả trong danh sách.';return;}if(totalEditor.select('misc-'+e.url)){el('totalViewport').scrollIntoView?.({behavior:'smooth',block:'center'});el('miscHint').textContent='Đã chọn '+e.file.name+'. Kéo ảnh trong Ảnh tổng; kéo góc để đổi ngang/cao, có thể đưa ra ngoài vùng xe.';}};
el('miscMoveItem').onchange=()=>{renderMiscPreview();syncMiscPositionFields();};
el('applyMiscPosition').onclick=()=>{const e=movingMisc();if(!e)return;const values=['miscX','miscY','miscW','miscH'].map(id=>Number(el(id).value)/100);if(!values.every(Number.isFinite)){el('miscHint').textContent='Vị trí chưa hợp lệ';return;}setMiscPosition(e,...values);invalidate();renderMiscPreview();syncMiscPositionFields();scheduleCompose();};
el('resetMiscPosition').onclick=()=>{const e=movingMisc();if(!e)return;delete e.miscPosition;totalEditor.forget('misc-'+e.url);invalidate();renderMiscPreview();syncMiscPositionFields();scheduleCompose();};
let miscDrag=null;
el('miscPreview').onpointerdown=()=>{};
el('miscPreview').onpointermove=event=>{if(!miscDrag)return;const c=el('miscPreview'),r=c.getBoundingClientRect(),x=(event.clientX-r.left)*c.width/r.width,y=(event.clientY-r.top)*c.height/r.height;setMiscPosition(miscDrag.entry,(x-miscDrag.x)/c.width,(y-miscDrag.y)/c.height,miscDrag.w,miscDrag.h);renderMiscPreview();syncMiscPositionFields();};
el('miscPreview').onpointerup=()=>{if(!miscDrag)return;miscDrag=null;invalidate();scheduleCompose();};el('miscPreview').onpointercancel=()=>{if(miscDrag){miscDrag=null;invalidate();scheduleCompose();}};

// Each character owns its level and badge; these stay with the image when reordered.
function renderCharacters(){const list=el('characterItems');list.replaceChildren();for(const k of ['normal','showroom'])groups[k].forEach((e,i)=>{const card=document.createElement('div');card.className='item';attachEntryDrag(card,e,k);const im=document.createElement('img');im.draggable=false;try{im.src=cut(groupCrop(e,k),[0,0,groupCrop(e,k).width,groupCrop(e,k).height],200).toDataURL();}catch{im.src=e.url;}const name=document.createElement('small');name.textContent=(i+1)+'. '+e.file.name+' · '+(i<(el('featured').value==='auto'?currentCharacterForm(groups[k].length).featured:el('featured').value==='manual'?Number(el('featuredN').value):Number(el('featured').value))?'Nổi bật':'Nhân vật thường');const levelLabel=document.createElement('label');levelLabel.textContent='Level Thánh Giáp';const level=document.createElement('input');level.type='number';level.min='0';level.max='999';level.placeholder='Để trống nếu không có';level.value=e.armorLevel??'';level.onchange=()=>{const n=Number(level.value);if(level.value!==''&&(!Number.isInteger(n)||n<0||n>999)){level.setCustomValidity?.('Level từ 0 đến 999');level.reportValidity?.();return;}level.setCustomValidity?.('');e.armorLevel=level.value===''?null:n;invalidate();scheduleCompose();};levelLabel.append(level);const effect=document.createElement('select');for(const [value,label]of [['none','Không effect'],['star','Ngôi sao vàng'],['vip','VIP vàng'],['hot','HOT'],['A','VIP + Chữ A'],['B','VIP + Chữ B'],['custom','PNG riêng']]){const op=document.createElement('option');op.value=value;op.textContent=label;effect.append(op);}effect.value=e.characterEffect||'none';effect.onchange=()=>{e.characterEffect=effect.value;invalidate();scheduleCompose();};const upload=document.createElement('input');upload.type='file';upload.accept='image/png,image/webp';upload.onchange=async()=>{const file=upload.files?.[0];if(!file)return;const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=url;});e.effectImage=img;e.characterEffect='custom';effect.value='custom';invalidate();scheduleCompose();}catch{el('characterHint').textContent='Không đọc được PNG effect';}finally{URL.revokeObjectURL(url);}};card.append(im,name,entryOrderControl(e,k),levelLabel,effect,upload);list.append(card);});}
function characterImage(e,k){const base=groupCrop(e,k),level=e.armorLevel,effect=e.characterEffect||'none';if((level===null||level===undefined)&&effect==='none')return base;const c=mk(base.width,base.height),ctx=c.getContext('2d');ctx.drawImage(base,0,0);const w=c.width,h=c.height;ctx.save();ctx.lineJoin='round';if(level!==null&&level!==undefined||effect==='star'){if(!armorStar)throw Error('Không tải được sao Thánh Giáp. Kiểm tra ui/assets/armor-star.png');const sw=w*.38,sh=sw*armorStar.height/armorStar.width;ctx.drawImage(armorStar,Math.min(w*.81-sw/2,w-sw-1),w*(.065+.31+.045),sw,sh);}
if(level!==null&&level!==undefined){ctx.textAlign='center';ctx.textBaseline='alphabetic';let size=w*.45;const label=String(level);ctx.font='900 '+size+'px Arial Black, Arial, sans-serif';let measure=ctx.measureText(label),glyphH=(measure.actualBoundingBoxAscent||size*.8)+(measure.actualBoundingBoxDescent||0);size*=Math.min(w*.31/glyphH,w*.27/measure.width);ctx.font='900 '+size+'px Arial Black, Arial, sans-serif';measure=ctx.measureText(label);const y=w*.065+(measure.actualBoundingBoxAscent||size*.8);ctx.strokeStyle='#ff2920';ctx.lineWidth=Math.max(2,w*.024)+2;ctx.fillStyle='#fff';ctx.strokeText(label,w*.81,y);ctx.fillText(label,w*.81,y);}
if(effect==='vip'||effect==='hot'||effect==='A'||effect==='B'){const image=armorEffects[['A','B'].includes(effect)?'vip':effect];if(!image)throw Error('Không tải được PNG '+effect.toUpperCase()+'. Kiểm tra thư mục ui/assets.');const dw=w*.55*.70,dh=dw*image.height/image.width,hasLevel=level!==null&&level!==undefined;const vx=w-dw-w*.005,vy=hasLevel?w*.80:h*.025;ctx.drawImage(image,vx,vy,dw,dh);if(effect==='A'||effect==='B'){let size=w*.45;ctx.font='900 '+size+'px '+ticketFont;let m=ctx.measureText(effect);size*=Math.min(w*.31/((m.actualBoundingBoxAscent||size*.8)+(m.actualBoundingBoxDescent||0)),w*.27/m.width,(h-vy-dh-w*.025)/(size));size=Math.max(1,size);ctx.font='900 '+size+'px '+ticketFont;m=ctx.measureText(effect);ctx.textAlign='center';ctx.textBaseline='alphabetic';ctx.fillStyle='#fff';ctx.strokeStyle='#ff0000';ctx.lineWidth=Math.max(2,w*.024)+2;const y=vy+dh+w*.015+(m.actualBoundingBoxAscent||size*.8);ctx.strokeText(effect,vx+dw/2,y);ctx.fillText(effect,vx+dw/2,y);}}
if(effect==='custom'&&e.effectImage){const ratio=Math.min(w*.55/e.effectImage.width,h*.3/e.effectImage.height)*.70,dw=e.effectImage.width*ratio,dh=e.effectImage.height*ratio;ctx.drawImage(e.effectImage,w-dw-w*.005,h*.025,dw,dh);}ctx.restore();return c;}
